const STRONG_HOUSE = ["อัตตะ", "ตนุ", "พันธุ", "ศุภะ"], EMPH_X = 1.25;   // หมายเหตุ ๑: แสดงชัดเป็นพิเศษเมื่อสัมพันธ์ถึงเรือนเหล่านี้
// ดาวเด่น–ดาวเสีย (ภาค ๑ หน้า ๓๕–๓๗): เรือนให้คุณ + ฐานบวกคุณภาพสูง + สัมพันธ์ดี = เด่น · กลับกัน = เสีย · แสดงคำอ่าน ไม่นับคะแนน
function strongRead(L, house, sq, relV, Ln, sum) {
  if (!PSTRONG[L]) return null;
  const h = Math.sign(houseTone(house)), q = sq.q >= 1.5 ? 1 : sq.q <= 0.5 ? -1 : 0, r = Math.sign(relV || 0);
  const lv = clamp(h + q + r, -2, 2);
  const head = { 2: "ดาวเด่น", 1: "ค่อนไปทางเด่น", 0: "ออกทั้งด้านดีและเสีย", "-1": "ค่อนไปทางอ่อน", "-2": "ดาวอ่อน" }[lv];
  const why = `เรือน${house}${h > 0 ? "ให้คุณ" : h < 0 ? "ให้โทษ" : "กลาง"} · ฐานรวม ${TH(sum)} ${sq.txt} · ความสัมพันธ์${r > 0 ? "ดี" : r < 0 ? "ไม่ดี" : "กลางๆ"}`;
  const txt = lv > 0 ? PSTRONG[L][0] : lv < 0 ? PSTRONG[L][1] : `ดี: ${PSTRONG[L][0]} / เสีย: ${PSTRONG[L][1]}`;
  const emph = [...new Set((Ln || []).filter(x => STRONG_HOUSE.includes(x.h)).map(x => x.h))];
  const X = PSTRONG_X[sum], xt = X ? `ฐานกำลัง${X[0]} (${TH(sum)}): ${sq.q >= 1.5 ? X[1] : sq.q <= 0.5 ? X[2] : `ดี: ${X[1]} / เสีย: ${X[2]}`}` : "";
  return { lv, head, why, txt, emph, xt, line: `${head} – ${P[L].n}: ${txt}${emph.length ? ` · แสดงชัดเป็นพิเศษ (เลขเดียวกับ${emph.join(" ")})` : ""}` };
}
