// เลขไทยทั้งหมด ยกเว้นเวลา (HH:MM[:SS]) และส่วนที่ครอบด้วย KEEP (เช่น ตัวเลขในตารางเลข ๗ ตัว / เลขเวลา)
const KEEP = "\u2063";
const keep = s => `${KEEP}${s}${KEEP}`;
const THD = "๐๑๒๓๔๕๖๗๘๙";
const thaiNum = s => String(s).split(KEEP).map((seg, i) => (i % 2 ? seg : seg.replace(/\d{1,2}:\d{2}(?::\d{2})?|\d/g, m => (m.length > 1 ? m : THD[m])))).join("");
