const esc = s => String(s === null || s === undefined ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const VCLS = { "เป็นคุณ": "good", "เป็นกลาง": "mid", "เป็นโทษ": "bad" };
const LVC = lv => (lv === "mix" ? "mix" : lv);
const SUBN = ["ยามต้น", "ยามกลาง", "ยามปลาย"];

function moonEmoji(L) {
  if (!L || !L.phase || !L.kham) return "🌙";
  const k = L.kham;
  if (L.phase === "ขึ้น") return k <= 5 ? "🌒" : k <= 9 ? "🌓" : k <= 14 ? "🌔" : "🌕";
  return k <= 5 ? "🌖" : k <= 9 ? "🌗" : k <= 14 ? "🌘" : "🌑";
}
// ยามถัดไป n ยาม (ข้ามกลางวัน→กลางคืน→วันใหม่ได้) พร้อมผลยามต้น/กลาง/ปลาย – คำนวณจากผังใน snapshot
function upcomingYams(snap, n) {
  const ch = snap.chart;
  let dayIdx = ch.dayIdx, isNight = ch.isNight, no = ch.yamNo + 1, start = new Date(snap.yamEnd), rows = ch.rows;
  const out = [];
  while (out.length < n) {
    if (no > 8) {
      no = 1;
      if (!isNight) isNight = true;
      else {
        isNight = false; dayIdx = (dayIdx + 1) % 7;
        const day = [...Array(7)].map((_, i) => step(dayIdx + 1, i));
        rows = { day, month: rows.month, year: rows.year, sum: day.map((v, i) => v + rows.month[i] + rows.year[i]) };
      }
    }
    const lord = step(dayIdx + 1, (isNight ? 4 : 5) * (no - 1));
    const taksaLord = (dayIdx === 3 && isNight) ? 8 : dayIdx + 1;
    const subs = [0, 1, 2].map(k => { const rk = CFG.subRows[k]; return analyze({ rows, yamLord: lord, rowKey: rk, col: rows[rk].indexOf(lord), taksaLord }).verdict; });
    out.push({ no, lord, start: new Date(start), isNight, subs });
    start = new Date(start.getTime() + CFG.yamMinutes * 60000); no++;
  }
  return out;
}

// ตารางยามทั้งช่วง (กลางวัน/กลางคืน 8 ยาม) พร้อมผลของยามต้น/กลาง/ปลายแต่ละยาม – คำนวณจากผังใน snapshot
function yamTimeline(snap) {
  const ch = snap.chart, c = chartOfSnap(snap);
  const yamEnd = new Date(snap.yamEnd), yamStart = new Date(yamEnd.getTime() - CFG.yamMinutes * 60000);
  const t0 = new Date(yamStart.getTime() - (ch.yamNo - 1) * CFG.yamMinutes * 60000);
  const out = [];
  for (let i = 0; i < 8; i++) {
    const lord = step(ch.dayIdx + 1, (ch.isNight ? 4 : 5) * i);
    const s = new Date(t0.getTime() + i * CFG.yamMinutes * 60000);
    const subs = [0, 1, 2].map(k => {
      const rk = CFG.subRows[k];
      return analyze({ ...c, yamLord: lord, rowKey: rk, col: ch.rows[rk].indexOf(lord) }).verdict;
    });
    out.push({ no: i + 1, lord, start: s, end: new Date(s.getTime() + CFG.yamMinutes * 60000), subs, now: i === ch.yamNo - 1 });
  }
  return out;
}


// ================= ตาราง 7 ตัวที่ 2 (v6.9): ตั้งจากเวลาแบบ ๑๒ ชม. =================
// ฐานวัน = ชั่วโมง (๑๒ ชม.) ถ้าเกิน ๗ หัก ๗ (๘→๑ … ๑๒→๕ · เที่ยงคืน 00:xx = ๑๒ → ๕) · ฐานเดือน = นาทีตัวแรก · ฐานปี = นาทีตัวหลัง
// นาที ๐ แทนด้วย ๗ · ๘ ๙ หัก ๗ เป็น ๑ ๒ · เช่น 10:09 → ๓ ๗ ๒ · 21:00 → ๙ นาฬิกา → ๒ ๗ ๗ · ตารางวนซ้ำทุก ๑๒ ชม.
const dig7 = d => (d === 0 ? 7 : mod7(d));   // ๐ → ๗ · เกิน ๗ หัก ๗ (๘→๑ ๙→๒ … ๑๒→๕)
// v7.0 เลือกแบบตั้งยามได้ (ตั้งค่า t2Mode ใน settings.json) · "12" = แบบ v6.9 (ค่าเริ่มต้น) · "24" = สามตัวท้ายของ HHMM แบบ v6.8.1
// แบบ ๒๔ ชม.: ฐานวัน = หลักหน่วยของชั่วโมง · ฐานเดือน = นาทีตัวแรก · ฐานปี = นาทีตัวหลัง (๐ → ๗ · ๘ ๙ → ๑ ๒) · เช่น 10:09 → ๗ ๗ ๒
let T2M = "12";   // แบบของตารางที่คำนวณล่าสุด → ใช้เลือกชุดเกณฑ์ ๒๘ เรื่อง (CAL.topic12 / CAL.topic24)
const T2MODE_TH = { "12": "แบบ ๑๒ ชม.", "24": "แบบ ๒๔ ชม." };
const normT2M = m => (String(m) === "24" ? "24" : "12");
// v7.7.0 ขนาดตัวอักษร ๓ ระดับ (0 ปกติ = ขนาดเดิม · 1 ใหญ่ ≈ satta7 ปกติ · 2 ใหญ่มาก ≈ satta7 ใหญ่) เก็บใน settings.json คีย์ fontLevel
const FS_TH = ["ปกติ", "ใหญ่", "ใหญ่มาก"];
const normFS = v => (["0", "1", "2"].includes(String(v)) ? +v : 1);
const fsSet = () => { try { return normFS((readJSON(F_SETTINGS) || {}).fontLevel); } catch (e) { return 1; } };
// ชื่อภพยาวย่อขนาดตามจำนวนพยัญชนะ/สระที่กินที่ (ไม่นับสระบน-ล่าง วรรณยุกต์) แทนการตัด "…" เหมือน satta7
const thLen = t => String(t).replace(/[\u0E31\u0E34-\u0E3A\u0E47-\u0E4E]/g, "").length;
const nmCls = t => { const n = thLen(t); return n >= 10 ? ` class="n10"` : n === 9 ? ` class="n9"` : n === 8 ? ` class="n8"` : ""; };
const t2ModeSet = () => { try { return normT2M((readJSON(F_SETTINGS) || {}).t2Mode); } catch (e) { return "12"; } };
const verNum = v => String(v || "0").split(".").map(Number).reduce((x, n, i) => x + (n || 0) / Math.pow(100, i), 0);
// ผลเก่าที่ไม่ได้บันทึกแบบไว้: ก่อน v6.9 = ๒๔ ชม. · v6.9 = ๑๒ ชม.
const t2ModeOf = snap => (snap && (snap.t2Mode === "12" || snap.t2Mode === "24")) ? snap.t2Mode : (snap && verNum(snap.version) < 6.09 ? "24" : "12");
function table2Of(when, ch, mode) {
  mode = normT2M(mode); T2M = mode;
  const h = when.getHours(), mi = when.getMinutes();
  const h12 = h % 12 || 12, raw = [mode === "24" ? h % 10 : h12, Math.floor(mi / 10), mi % 10];
  const code = raw;                                      // ตัวเลขดิบ (ชั่วโมง · นาทีตัวแรก · ตัวหลัง) ไว้แสดงที่มา
  const start = raw.map(dig7);                           // ๐ → ๗ · เกิน ๗ หัก ๗
  const rows = {
    day:   [...Array(7)].map((_, i) => step(start[0], i)),
    month: [...Array(7)].map((_, i) => step(start[1], i)),
    year:  [...Array(7)].map((_, i) => step(start[2], i))
  };
  rows.sum = rows.day.map((v, i) => v + rows.month[i] + rows.year[i]);
  const col = rows[ch.rowKey].indexOf(ch.yamLord);       // ใช้ดาวแกนเดิม + แถวเดิม (ยามต้น/กลาง/ปลาย) หาตำแหน่งในตารางใหม่
  const taksaLord = (ch.dayIdx === 3 && ch.isNight) ? 8 : ch.dayIdx + 1;
  const a = analyze({ rows, col, yamLord: ch.yamLord, rowKey: ch.rowKey, taksaLord });
  return { raw, code, start, rows, col, a, h12, mode, hhmm: `${pad2(h)}${pad2(mi)}`, text: start.join("") };
}
// ที่มาของเลขตั้งต้น (ใช้ทั้งหน้าแอปและคำสั่งลัด) เช่น “๑๐ นาฬิกา → ๓ · นาที ๐ → ๗ · ๙ → ๒”
function seedTxt(t2) {
  const [h, a, b] = t2.raw, [x, y, z] = t2.start, f = (d, v) => (d === v ? TH(d) : `${TH(d)} → ${TH(v)}`);
  if (t2.mode === "24") return `สามตัวท้าย ${TH(h)}${TH(a)}${TH(b)} → ${f(h, x)} · ${f(a, y)} · ${f(b, z)}`;
  return `${TH(h)} นาฬิกา${h === x ? "" : ` → ${TH(x)}`} · นาที ${f(a, y)} · ${f(b, z)}`;
}
