  items.push({ v: g > 0 ? 0.5 : g < 0 ? -0.5 : 0, t: `ดาวประธาน${P[L].n}เป็น${role} (${TAKSA_GRP_TH[g]}) ตกเรือน${lagnaHouse} → ${how}` });
