// ฐานรวม หน้า กลาง ท้าย (ภาค ๑ หน้า ๔๖–๔๘): หลัก ๑ ๔ ๗
function fmeRead(R) {
  const s = [R.sum[0], R.sum[3], R.sum[6]], bad = s.map(x => SUM_PAP.includes(x)), good = s.map(x => SUM_SUP.includes(x));
  const lines = [];
  if (FRONT_TXT[s[0]]) lines.push(`ฐานหน้า ${TH(s[0])}: ${FRONT_TXT[s[0]]}`);
  if (bad.every(Boolean)) lines.push("บาปเคราะห์หาบชะตา (ร้ายทั้งหน้า กลาง ท้าย): แม้มีทรัพย์ก็หาความสุขทางใจได้ยาก");
  else {
    if (bad[0]) lines.push(`ฐานหน้า ${TH(s[0])} ร้าย: ความผิดพลาดมักมาจากการกระทำของตนเอง`);
    if (bad[1]) lines.push(`ฐานกลาง ${TH(s[1])} ร้าย: ความเดือดร้อนมาจากพ่อแม่ ญาติพี่น้อง บุตรบริวาร`);
    if (bad[2]) lines.push(`ฐานท้าย ${TH(s[2])} ร้าย: ความเดือดร้อนมาจากคู่ครอง เพศตรงข้าม หรือหุ้นส่วน`);
    if (good.every(Boolean)) lines.push("ฐานหน้า กลาง ท้ายเป็นฝ่ายดีทั้งหมด: มีความสุขทางใจ ยอมรับสิ่งที่เกิดขึ้นตามจริง");
  }
  return { s, bad, good, lines };
}
